for (const record of Object.values(records)) {
  for (const locale of ['en', 'ar', 'ru'] as const) {
    if (!record.content[locale]) {
      record.content[locale] = localizeFromPersian(record, locale);
    }
  }
}

export const specialtySystemSpecs = [
  tensileFabricMembraneStructuresSpec,
  retractableRoofCoveringSystemsSpec,
  etfeRoofFacadeSystemsSpec
];

export function getSpecialtySystemPage(slug: SpecialtySystemSlug, locale: Locale): ServicePageTemplateData {
  const record = records[slug];
  const content = record.content[locale];

  return {
    id: record.id,
    routes: record.routes,
    ...content,
    schemas: {
      organization: true
    }
  };
}
